update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(17,null::text,$$Assistência educacional$$,$$A assistência educacional compreende a instrução escolar e a formação profissional do preso e do internado.$$),
(18,null,$$Ensino de primeiro grau$$,$$O ensino de primeiro grau é obrigatório e se integra ao sistema escolar da unidade federativa.$$),
(18,$$Art. 18-A$$,$$Ensino médio nos presídios$$,$$O ensino médio, regular ou supletivo, com formação geral ou educação profissional de nível médio, deve ser implantado nos presídios. O ensino integra o sistema estadual e municipal e conta com apoio da União (§ 1º), com cursos supletivos de jovens e adultos (§ 2º) e com programas de educação à distância (§ 3º).$$),
(19,null,$$Ensino profissional$$,$$O ensino profissional é ministrado em nível de iniciação ou de aperfeiçoamento técnico. Pelo parágrafo único, a mulher condenada terá ensino profissional adequado à sua condição.$$),
(20,null,$$Convênios educacionais$$,$$As atividades educacionais podem ser objeto de convênio com entidades públicas ou particulares que instalem escolas ou ofereçam cursos especializados.$$),
(21,null,$$Biblioteca$$,$$Cada estabelecimento deve ter uma biblioteca, para uso de todas as categorias de reclusos, com livros instrutivos, recreativos e didáticos, em atendimento às condições locais.$$),
(21,$$Art. 21-A$$,$$Censo penitenciário$$,$$O censo penitenciário deve apurar o nível de escolaridade (inciso I), a existência de cursos fundamentais e médios (inciso II) e profissionais (inciso III), a existência de bibliotecas e as condições do acervo (inciso IV) e outros dados relevantes para o aprimoramento educacional (inciso V).$$),
(22,null,$$Assistência social$$,$$A assistência social tem por finalidade amparar o preso e o internado e prepará-los para o retorno à liberdade.$$),
(23,null,$$Incumbências do serviço social$$,$$Cabe ao serviço de assistência social, entre outras tarefas, conhecer os resultados de diagnósticos e exames (inciso I), relatar ao diretor os problemas do assistido (inciso II), acompanhar saídas (inciso III), orientar o assistido na fase final da pena (inciso V), providenciar documentos e benefícios (inciso VI) e amparar a família do preso, do internado e da vítima (inciso VII).$$),
(24,null,$$Assistência religiosa$$,$$A assistência religiosa, com liberdade de culto, é prestada aos presos e aos internados, com participação nos serviços do estabelecimento e posse de livros de instrução religiosa. Deve haver local apropriado para os cultos (§ 1º), e ninguém pode ser obrigado a participar de atividade religiosa (§ 2º).$$),
(25,null,$$Assistência ao egresso$$,$$A assistência ao egresso consiste em orientação e apoio para reintegrá-lo à vida em liberdade (inciso I) e, se necessário, em alojamento e alimentação por dois meses (inciso II). O parágrafo único permite uma única prorrogação desse prazo, mediante declaração do assistente social sobre o empenho na obtenção de emprego.$$),
(26,null,$$Conceito de egresso$$,$$Considera-se egresso, para os efeitos da lei, o liberado definitivo, pelo prazo de um ano a contar da saída do estabelecimento (inciso I), e o liberado condicional, durante o período de prova (inciso II).$$),
(27,null,$$Colaboração para o trabalho do egresso$$,$$O serviço de assistência social colabora com o egresso na obtenção de trabalho.$$),
(28,null,$$Trabalho do condenado$$,$$O trabalho do condenado é dever social e condição de dignidade humana, com finalidade educativa e produtiva. Aplicam-se a ele precauções de segurança e higiene (§ 1º), e o trabalho do preso não está sujeito à Consolidação das Leis do Trabalho (§ 2º).$$),
(29,null,$$Remuneração do trabalho$$,$$O trabalho do preso é remunerado, mediante prévia tabela, em valor não inferior a três quartos do salário mínimo. A remuneração atende à indenização do dano do crime, à assistência à família, a pequenas despesas pessoais e ao ressarcimento ao Estado (§ 1º, a a d), e a parte restante forma pecúlio em caderneta de poupança (§ 2º).$$),
(30,null,$$Prestação de serviço à comunidade$$,$$As tarefas executadas como prestação de serviço à comunidade não são remuneradas.$$),
(31,null,$$Obrigatoriedade do trabalho$$,$$O condenado à pena privativa de liberdade está obrigado ao trabalho na medida de suas aptidões e capacidade. Para o preso provisório, o trabalho não é obrigatório e só pode ser executado no interior do estabelecimento (parágrafo único).$$),
(32,null,$$Atribuição do trabalho$$,$$Na atribuição do trabalho consideram-se a habilitação, a condição pessoal, as necessidades futuras do preso e as oportunidades do mercado. Limita-se o artesanato sem expressão econômica (§ 1º), os maiores de sessenta anos podem solicitar ocupação adequada à idade (§ 2º) e doentes ou deficientes físicos exercem só atividades apropriadas ao seu estado (§ 3º).$$),
(33,null,$$Jornada de trabalho$$,$$A jornada normal de trabalho não pode ser inferior a seis nem superior a oito horas, com descanso nos domingos e feriados. O parágrafo único admite horário especial para presos designados para serviços de conservação e manutenção do estabelecimento.$$),
(34,null,$$Gerenciamento do trabalho$$,$$O trabalho pode ser gerenciado por fundação ou empresa pública com autonomia administrativa, com objetivo de formação profissional do condenado. A entidade promove e supervisiona a produção, comercializa e suporta as despesas (§ 1º), e os governos podem celebrar convênio com a iniciativa privada para oficinas de trabalho de apoio dos presídios (§ 2º).$$),
(35,null,$$Aquisição dos produtos do trabalho prisional$$,$$Os órgãos da administração direta ou indireta adquirem, com dispensa de concorrência pública, os bens ou produtos do trabalho prisional, quando não for possível ou recomendável a venda a particulares. As importâncias arrecadadas revertem em favor da fundação ou empresa pública do artigo anterior ou, na falta, do estabelecimento penal (parágrafo único).$$),
(36,null,$$Trabalho externo no regime fechado$$,$$O preso em regime fechado só pode prestar trabalho externo em serviço ou obras públicas realizados por órgãos da administração direta ou indireta, ou por entidades privadas, com cautelas contra a fuga e em favor da disciplina. O limite é de dez por cento dos empregados da obra (§ 1º), a remuneração cabe ao órgão, entidade ou empresa (§ 2º), e o trabalho para entidade privada depende do consentimento expresso do preso (§ 3º).$$),
(37,null,$$Autorização do trabalho externo$$,$$A autorização de trabalho externo, dada pela direção do estabelecimento, depende de aptidão, disciplina e responsabilidade, além do cumprimento mínimo de um sexto da pena. Será revogada se o preso praticar crime, for punido por falta grave ou contrariar os requisitos do artigo (parágrafo único).$$)
) as v(n,t,c,a) where l.codigo='lep' and l.numero=v.n and l.titulo is not distinct from v.t and l.inciso is null and l.paragrafo is null and l.texto like 'Art%' and l.vigente;